import{_ as r,o as l,c as o,ag as a}from"./chunks/framework.DWOJQht4.js";const c=JSON.parse('{"title":"项目介绍","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md","lastUpdated":1792595694000}'),i={name:"guide/introduction.md"};function n(e,t,s,g,h,u){return l(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="项目介绍" tabindex="-1">项目介绍 <a class="header-anchor" href="#项目介绍" aria-label="Permalink to &quot;项目介绍&quot;">​</a></h1><h2 id="什么是-cloudctf" tabindex="-1">什么是 CloudCTF？ <a class="header-anchor" href="#什么是-cloudctf" aria-label="Permalink to &quot;什么是 CloudCTF？&quot;">​</a></h2><p>CloudCTF 是一个企业级 CTF（Capture The Flag）竞赛与安全培训平台，专为企业、教育机构和安全团队打造。平台提供完整的私有化部署方案，帮助组织快速搭建专属的网络安全竞赛和培训环境。</p><p>在线预览环境：</p><ul><li><a href="http://cloud-ctf.lostpeach.cn/" target="_blank" rel="noreferrer">http://cloud-ctf.lostpeach.cn/</a></li></ul><h2 id="为什么需要-ctf-平台" tabindex="-1">为什么需要 CTF 平台？ <a class="header-anchor" href="#为什么需要-ctf-平台" aria-label="Permalink to &quot;为什么需要 CTF 平台？&quot;">​</a></h2><h3 id="企业安全培训痛点" tabindex="-1">企业安全培训痛点 <a class="header-anchor" href="#企业安全培训痛点" aria-label="Permalink to &quot;企业安全培训痛点&quot;">​</a></h3><ul><li><strong>培训成本高</strong>：外部培训费用昂贵，且无法持续进行</li><li><strong>实战环境缺乏</strong>：理论培训多，实战演练少</li><li><strong>效果难评估</strong>：无法量化培训效果和人员能力</li><li><strong>题库资源少</strong>：缺少真实漏洞环境和练习题目</li></ul><h3 id="cloudctf-解决方案" tabindex="-1">CloudCTF 解决方案 <a class="header-anchor" href="#cloudctf-解决方案" aria-label="Permalink to &quot;CloudCTF 解决方案&quot;">​</a></h3><ul><li><strong>一次投入，长期使用</strong>：私有化部署，无需按用户付费</li><li><strong>内置题库</strong>：集成 Vulhub 漏洞库，数百个真实漏洞环境</li><li><strong>数据可视化</strong>：详细的培训数据和能力评估报告</li><li><strong>灵活定制</strong>：支持多种赛制和培训模式</li></ul><h2 id="核心功能" tabindex="-1">核心功能 <a class="header-anchor" href="#核心功能" aria-label="Permalink to &quot;核心功能&quot;">​</a></h2><h3 id="🏆-多场景支持" tabindex="-1">🏆 多场景支持 <a class="header-anchor" href="#🏆-多场景支持" aria-label="Permalink to &quot;🏆 多场景支持&quot;">​</a></h3><ul><li><strong>CTF 竞赛</strong>：个人赛、团队赛，支持同时举办多场比赛</li><li><strong>日常练习</strong>：题库练习模式，随时随地提升技能</li><li><strong>理论考核</strong>：选择题、判断题、填空题等题型</li><li><strong>漏洞复现</strong>：一键部署真实漏洞环境，实战化培训</li></ul><h3 id="📚-丰富的题库资源" tabindex="-1">📚 丰富的题库资源 <a class="header-anchor" href="#📚-丰富的题库资源" aria-label="Permalink to &quot;📚 丰富的题库资源&quot;">​</a></h3><ul><li><strong>Vulhub 集成</strong>：自动导入 Vulhub 漏洞环境</li><li><strong>CVE/CNVD 支持</strong>：支持主流漏洞库</li><li><strong>多种题型</strong>：Web、Pwn、Reverse、Crypto、Misc</li><li><strong>自定义题目</strong>：支持上传自定义题目和环境</li></ul><h3 id="🎯-智能化管理" tabindex="-1">🎯 智能化管理 <a class="header-anchor" href="#🎯-智能化管理" aria-label="Permalink to &quot;🎯 智能化管理&quot;">​</a></h3><ul><li><strong>动态靶场</strong>：自动化容器管理，每个用户独立环境</li><li><strong>动态 Flag</strong>：防止作弊，保证比赛公平</li><li><strong>资源限制</strong>：CPU、内存、网络限制，防止滥用</li><li><strong>自动回收</strong>：定时清理过期容器，节省资源</li></ul><h3 id="📊-数据分析" tabindex="-1">📊 数据分析 <a class="header-anchor" href="#📊-数据分析" aria-label="Permalink to &quot;📊 数据分析&quot;">​</a></h3><ul><li><strong>实时排行榜</strong>：实时更新，多维度统计</li><li><strong>能力评估</strong>：分析用户强项和弱项</li><li><strong>培训报告</strong>：生成详细的培训效果报告</li><li><strong>数据导出</strong>：支持导出 Excel/PDF 格式</li></ul><h2 id="应用场景" tabindex="-1">应用场景 <a class="header-anchor" href="#应用场景" aria-label="Permalink to &quot;应用场景&quot;">​</a></h2><h3 id="🏢-企业安全培训" tabindex="-1">🏢 企业安全培训 <a class="header-anchor" href="#🏢-企业安全培训" aria-label="Permalink to &quot;🏢 企业安全培训&quot;">​</a></h3><p><strong>适用对象</strong>：安全团队、开发团队、运维团队</p><ul><li><strong>新员工入职培训</strong>：通过理论考核和实战演练，快速提升安全意识</li><li><strong>定期技能考核</strong>：评估员工安全技能水平，发现培训短板</li><li><strong>应急演练</strong>：模拟真实攻击场景，提升应急响应能力</li><li><strong>团队竞赛</strong>：内部 CTF 比赛，激发学习热情</li></ul><p><strong>典型客户</strong>：金融机构、互联网公司、政府机关</p><h3 id="🎓-教育机构" tabindex="-1">🎓 教育机构 <a class="header-anchor" href="#🎓-教育机构" aria-label="Permalink to &quot;🎓 教育机构&quot;">​</a></h3><p><strong>适用对象</strong>：高校、职业院校、培训机构</p><ul><li><strong>网络安全课程</strong>：配合理论教学，提供实验环境</li><li><strong>学生竞赛</strong>：举办校内 CTF 比赛，选拔优秀人才</li><li><strong>毕业设计</strong>：提供真实项目环境</li><li><strong>技能认证</strong>：配合职业技能认证考试</li></ul><p><strong>典型客户</strong>：网络安全专业院校、职业培训机构</p><h3 id="🛡️-安全团队" tabindex="-1">🛡️ 安全团队 <a class="header-anchor" href="#🛡️-安全团队" aria-label="Permalink to &quot;🛡️ 安全团队&quot;">​</a></h3><p><strong>适用对象</strong>：红队、蓝队、安全研究团队</p><ul><li><strong>技能提升</strong>：日常练习，保持技术敏锐度</li><li><strong>漏洞研究</strong>：快速搭建漏洞复现环境</li><li><strong>工具测试</strong>：测试安全工具和脚本</li><li><strong>知识分享</strong>：团队内部技术分享和演示</li></ul><p><strong>典型客户</strong>：安全公司、企业安全部门</p><h3 id="🏆-竞赛组织方" tabindex="-1">🏆 竞赛组织方 <a class="header-anchor" href="#🏆-竞赛组织方" aria-label="Permalink to &quot;🏆 竞赛组织方&quot;">​</a></h3><p><strong>适用对象</strong>：赛事主办方、培训机构</p><ul><li><strong>公开赛事</strong>：举办面向社会的 CTF 比赛</li><li><strong>选拔赛</strong>：人才选拔和招聘</li><li><strong>培训班</strong>：配合培训课程使用</li><li><strong>认证考试</strong>：技能认证考试平台</li></ul><p><strong>典型客户</strong>：行业协会、培训机构、企业 HR</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="http://cloud-ctf.lostpeach.cn/" target="_blank" rel="noreferrer">在线预览</a> - 先体验已部署环境</li><li><a href="/CloudCTF/guide/quick-start.html">快速开始</a> - 5分钟部署你的第一个 CTF 平台</li><li><a href="/CloudCTF/guide/features.html">功能特性</a> - 了解详细功能</li><li><a href="/CloudCTF/guide/production-deploy.html">生产部署</a> - systemd 与反向代理部署</li></ul>',38)])])}const p=r(i,[["render",n]]);export{c as __pageData,p as default};
